reactiveclass Consumer() {
	statevars {
		int bufferSize;
		int buffer[10];
		int head;
		int tail;
	}

	Consumer() {
		bufferSize = 0;
		head = 0;
		tail = 0;
	}

	msgsrv initial() {
		// no automatic behavior
	}

	msgsrv Item(int data) {
		if (bufferSize < 10) {
			buffer[tail] = data;
			tail = (tail + 1) % 10;
			bufferSize = bufferSize + 1;
		}
	}

	msgsrv Consume() {
		if (bufferSize > 0) {
			int item;
			item = buffer[head];
			head = (head + 1) % 10;
			bufferSize = bufferSize - 1;
		} else {
			// buffer empty
		}
	}
}

main {
	Consumer consumer();
	Producer producer(consumer);

	producer.Produce(1);
	producer.Produce(2);
	consumer.Consume();
}

